UPDATE TB_LMS_SBJCT
SET DVCLAS_NCKNM = #{dvclasNcknm}
  , MDFR_ID      = #{mdfrId}
  , MOD_DTTM     = TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
WHERE SBJCT_ID = #{sbjctId}
  AND DVCLAS_NO = #{dvclasNo}
  AND DELYN = 'N'

mapper.select:
SELECT A.TASK_TYCD , A."KEY" AS KEY_COL , A.KEY_MSG , A.MSG , A.LANG_CD FROM TB_LMS_MLTLANG_SRPT_MSG A WHERE 1 = 1
AND A.TASK_TYCD = #{taskTycd}
AND A."KEY" = #{key}
ORDER BY A.LANG_CD, A.KEY_MSG
